import test from "node:test";
import assert from "node:assert/strict";
import {extend,liveSource,normalize,image,price,action} from "./business.mjs";
const id="12345678-1234-1234-1234-123456789012", kinds=["services","cyber","accommodation","transport","properties","sellers"];
const row={kind:"services",id,partner_id:id,title:"Public test <script>",description:"Contact 0712345678 or test@example.com",location:"Siaya",price_from:50,pricing_model:"fixed",image_bucket:"service-provider-public-media",image_path:"test/photo.jpg",private_field:"secret"};
const fixture=()=>kinds.map(kind=>({...row,kind,image_bucket:null,image_path:null,partner_id:kind==="properties"?null:id}));
const base=()=>({"sitemap.xml":"<urlset><url><loc>https://leogo.co.ke/</loc></url></urlset>","seo-catalogue/index.html":'<div class="navlinks"></div>'});
test("all six directories and individual pages generated",()=>{const files=extend(base(),fixture(),"https://leogo.co.ke");for(const kind of kinds){assert.ok(files["seo-catalogue/business/"+kind+"/index.html"]);assert.ok(files["seo-catalogue/business/"+kind+"/"+id+"/index.html"]);}assert.equal((files["sitemap.xml"].match(/<loc>/g)||[]).length,14);assert.ok(files["seo-catalogue/index.html"].includes("Services &amp; businesses"));});
test("empty sections do not invent providers; removed entries disappear",()=>{const files=extend(base(),[],"https://leogo.co.ke");assert.ok(files["seo-catalogue/business/services/index.html"].includes("No eligible individual listings"));assert.ok(!files["seo-catalogue/business/services/"+id+"/index.html"]);assert.ok(!files["sitemap.xml"].includes(id));});
test("public fields only, redact contacts, escape html and constrain media",()=>{const f=extend(base(),[row],"https://leogo.co.ke"),p=f["seo-catalogue/business/services/"+id+"/index.html"];assert.ok(p.includes("Public test &lt;script&gt;"));assert.ok(!p.includes("0712345678"));assert.ok(!p.includes("test@example.com"));assert.ok(!p.includes("secret"));assert.ok(p.includes("service-provider-public-media/test/photo.jpg"));assert.equal(image({...row,image_bucket:"private"},false),"");assert.equal(image({...row,image_path:"test/../photo.jpg"},false),"");assert.throws(()=>normalize([{...row,kind:"premium"}]));assert.throws(()=>normalize([row,row]));});
test("staging blocks production links and images",()=>{const f=extend({"sitemap.xml":"<urlset></urlset>"},[row],"https://staging.invalid",true);const p=f["seo-catalogue/business/services/"+id+"/index.html"];assert.ok(p.includes("noindex,nofollow"));assert.ok(!p.includes("supabase.co"));assert.ok(!p.includes("business-action"));assert.ok(!p.includes("leogo.co.ke"));});
test("price units and existing partner routes",()=>{assert.equal(price(row),"KSh 50");assert.equal(price({...row,pricing_model:"quote"}),"Request a quote / check price");assert.equal(price({...row,kind:"accommodation",pricing_model:"from",unit:"night"}),"From KSh 50 / night");assert.ok(action(row).includes("partner_type=service_provider"));assert.equal(action({...row,kind:"properties"}),"/#vacant-houses");assert.throws(()=>liveSource("sb_secret_x"));});
test("live availability guards action and displays price",async()=>{async function simulate(rows,ok=true){const link={hidden:true,href:""},status={textContent:""},desc={textContent:""},h={textContent:""},photo={hidden:false},metas=[];const el={dataset:{businessId:"services/"+id},querySelectorAll:()=>[link],querySelector:s=>s==="h1"?h:photo};const doc={querySelectorAll:()=>[],querySelector:()=>el,getElementById:s=>s==="business-price"?status:s==="business-action"?link:desc,createElement:()=>({}),head:{append:m=>metas.push(m)}};const fetch=async(url,opts)=>{assert.ok(url.endsWith("/seo_public_business_v1"));assert.equal(opts.headers.apikey,"sb_publishable_test");return {ok,json:async()=>rows};};new Function("document","fetch",liveSource("sb_publishable_test"))(doc,fetch);for(let i=0;i<12;i++)await Promise.resolve();return {link,status,desc,metas,photo};}let s=await simulate([row]);assert.equal(s.status.textContent,"KSh 50");assert.equal(s.link.hidden,false);assert.ok(s.link.href.includes("partner_id="+id));s=await simulate([]);assert.equal(s.link.hidden,true);assert.equal(s.metas[0].content,"noindex");assert.equal(s.photo.hidden,true);s=await simulate([],false);assert.equal(s.link.hidden,true);assert.ok(s.status.textContent.includes("unavailable"));});
